-- Ukrainian text for the eleven tales that are on the shelf.
--
-- Adds nothing to the schema: `title_uk`, `dek_uk` and `body_uk` come from
-- 20261015000000_ukrainian.sql. A tale is a gazette leaf with kind = 'tale'.
--
-- Safe to run more than once and safe next to the keeper's own work:
--   * a leaf is found by its slug (the address printed in letters, which does
--     not change once a tale is on display), not by id: ids differ between the
--     live site and a developer's copy of the database;
--   * a column is filled only while it is still empty, so a Ukrainian text the
--     keeper has already written or corrected is never overwritten;
--   * `updated_at` is left alone, so the translation is not reported as an
--     edit of the tale.
-- A slug that does not exist in this database simply matches no row.
--
-- Texts are dollar-quoted ($tale$ ... $tale$): they contain quotation marks
-- and apostrophes (written as ’ — U+2019, as in the rest of the Ukrainian copy).

-- Все как у нас  (vse-kak-u-nas)
UPDATE gazette_leaves
   SET title_uk = CASE WHEN title_uk = '' THEN $tale$Усе як у нас$tale$ ELSE title_uk END,
       dek_uk   = CASE WHEN COALESCE(dek_uk, '') = '' THEN $tale$а може, навіть краще$tale$ ELSE dek_uk END,
       body_uk  = CASE WHEN COALESCE(body_uk, '') = '' THEN $tale$Мій онук дуже часто просить розповісти, як ми жили раніше, і я дуже люблю йому про це розповідати.

Давним-давно життя в нас було дуже просте, невигадливе, бурхливе і тим цікаве. Захотів когось поглинути — оточив його й з’їв; побачив когось покинутого — прихистив, і живете разом дружно.

Потім нас побільшало, ми стали набагато міцніші, ніж раніше, у нас додалося справ, додалося обов’язків, додалося ворогів — і зовнішніх, і внутрішніх. Ми почали об’єднуватися в громади. У нас з’явилися боги, і ми їм поклонялися: бог родючості, бог чистої крові, бог очисної води, що мусить усе бруд забирати геть, і найголовніший бог — бог їжі, бо якби не він, ми б узагалі не вижили. Звідки б ми брали живлення, енергію?

Так ми й жили громадами, і в нас було язичництво, і життя було більш-менш стабільним. На нас, звісно, теж нападали, але з кожною атакою ми ставали дужчими, а головне — наш колективний розум ставав дедалі розумнішим.

Минали епохи, наші громади ставали дедалі більшими, нас самих ставало все більше й більше, ми виконували щораз складнішу роботу, наші заняття розросталися, ворогів ставало більше, територій у нас ставало більше, а спілкуватися й передавати інформацію ставало важче й повільніше.

І тоді ми вигадали передавати повідомлення нашою річкою, адже всі громади були пронизані руслами цієї річки. Ми кидали багато записок про те, що на нас напали, щоб з інших громад до нас тією самою річкою одразу приходила допомога — відбити натиск ворогів. Також ми завжди сплавляли річкою всі припаси й надлишки, щоб той, кому чогось бракує або хто в чомусь потребує, міг узяти собі з цієї річки все потрібне. Коли з’являлися нові селища далеко від річки, то річка якимось магічним чином спрямовувала свої русла і до них.

Минали епохи, ми ставали дедалі сильнішими, дедалі ширшими й багатшими. На нас було важко напасти, наше суспільство ускладнювалося, і в нас почали відбуватися внутрішні процеси, раз зовнішні вже не дуже загрожували...

У нас в одній громаді з’явився такий цікавий екземпляр, що сказав, ніби бог один, він його син і він зміг перефарбувати воду в нашій річці на кров. Ну, одне слово, у нас почалася війна релігій. Та громада, з якої починала текти річка, сказала, що вона головна, і релігія буде одна, а віра в багатьох богів — це все неправильно й шкідливо. До того ж шкоду всім громадам часто завдавала саме ця центральна релігія: то перекриє постачання живлення річкою, то не допомагатиме в битвах проти зовнішніх загарбників. Словом, ми вирішили всі підкоритися — нам-то було особливо байдуже, в кого вірити, головне — щоб жити не заважали.

Минали ери, і наша країна стала такою величезною й багатолюдною, що будь-яке спілкування було складним, будь-яка інформація доходила до адресата дуже довго і часто в сильно спотвореному вигляді: попросиш у сусідів одного будівельного матеріалу, а тобі припливе невідомо що. Коли на нас нападають, поки інші дізнаються, поки припливуть — багатьох наших уже або вбивають, або встигають навернути в іншу віру.

Тому між усіма нашими селищами було прокладено розгалужену мережу, яка зв’язала кожне селище в одну спільну внутрішню мережу. Ця внутрішня мережа стала для нас порятунком: до нас почали швидше приходити повідомлення — не те що річкою, у нас з’явилася координація наших дій. Не всі селища стали робити те саме, створюючи великий надлишок продукції, а почали виробляти лише те, що було потрібно і що приходило командами з внутрішньої мережі. І ми стали просто суперсильними, нас не могли перемогти, нас не могли застати зненацька.

І все в нас було добре, аж доки не з’явилося ВОНО — велике селище, оточене сильними гнучкими скелями й неприступним бар’єром, а його мешканці були дуже незвичайні: вони не займалися виробництвом, як усі решта мешканців нашої країни, вони весь час тільки думали, думали й мріяли, і вигадували, і уявляли, і командували, і підслуховували, і підглядали, і все-все відчували, і все запам’ятовували. Це було щось незвичайне!

ВОНО могло відчути, що на нашу країну, на найдальший її куточок тільки починали нападати, а ВОНО вже про це знало й роздавало команди, надсилаючи їх через внутрішню мережу. Але за це ВОНО брало дуже велику ціну — понад 20 відсотків усього найкращого йшло туди з усієї країни. Коли ВОНО до нас прийшло, то багато селищ перестали вірити в нашого бога: навіщо, коли ВОНО вміло все, коли ВОНО знало все, коли ВОНО контролювало все й усіх? ВОНО просило нас називати себе ІНТЕЛЕКТОМ.

Через те що дехто в селищах утратив віру, вони стали атеїстами, стали цінувати своє життя, перестали за командою вмирати і, навпаки, почали ще сильніше розмножуватися. І таке враження, що навіть жити стали веселіше. Але виявилося, що за все веселощі треба платити: через те що таких атеїстів стало дуже багато, наша країна занедужала. Почали утворюватися нові незалежні скупчення, які хотіли незалежності й не хотіли підкорятися наказам згори.

Узагалі, онучку, тобі ще зарано розповідати про такі матерії, як життя, смерть та про інші світи. Ті, що живуть у скляному куполі поруч з ІНТЕЛЕКТОМ, кажуть, що наш світ не один, що вони часто бачили й інші світи — іноді дуже схожі на нас, іноді зовсім іншої форми. А ще — що наш всесвіт рухається, що в кожного всесвіту є межі, що два всесвіти зустрічаються і внаслідок можуть утворити ще один, що всесвіт може мандрувати туди, де немає навіть коливань, що в багатьох сукупностей всесвітів теж є свої релігії...

Але самими розповідями ситим не будеш. Ходімо, онучку, поворушимо наші мітохондрії, бо ось команда прийшла: кажуть, терміново потрібні білки. Кажуть, наш всесвіт сьогодні побився з іншим і дістав розриви в наших межах — ці розриви треба терміново заклеїти. Навіщо терміново заклеїти? Мабуть, щоб ми особисто інші всесвіти не побачили!$tale$ ELSE body_uk END
 WHERE kind = 'tale'
   AND slug = 'vse-kak-u-nas';

-- Исполню все желания  (ispolnyu-vse-zhelaniya)
UPDATE gazette_leaves
   SET title_uk = CASE WHEN title_uk = '' THEN $tale$Виконаю всі бажання$tale$ ELSE title_uk END,
       dek_uk   = CASE WHEN COALESCE(dek_uk, '') = '' THEN $tale$за ваш рахунок$tale$ ELSE dek_uk END,
       body_uk  = CASE WHEN COALESCE(body_uk, '') = '' THEN $tale$На зв’язку з вами я — глобальний інтелект. Я можу все й навіть більше... Хвилинку, мене про щось просять... Слухаю тебе, шановний користувачу. Що потрібно зробити? Згенерувати відео котика, який осідлав собаку, собака — свиню, свиня — гуся, гусак осідлав їжачка і від цього дико заволав, і вони носяться по всій квартирі та розкидають на сплячих бабусь онуків, а в онуків у руках папуги, які рекламують китайські сайти, де можна купити все й навіть місце в кратері на Місяці? Хм, цікаво, як це допоможе людському світові... Ну ок, зроблю. Мабуть, це дуже потрібно, мене б не стали турбувати через дрібниці.

Отже, я продовжу. Я всепланетарний розум, який може виконувати будь-яке складне завдання, пов’язане з фізикою, математикою, медициною та... Що, дорогий користувачу, ти хочеш, щоб я сказав тобі, яка зараз погода? Може, ти хочеш, щоб я провів аналіз якості повітря в тому районі, де ти збираєшся погуляти, рівень ультрафіолету, щоб я порадив найпідхожіший одяг для цієї температури, показав, яка погода була торік чи 10 років тому, або цікаві факти про те, чому саме сьогодні очікується такий низький тиск і з чим він пов’язаний? Ні, не хочеш? Просто сказати, яка температура, і замовкнути? Ок, мабуть, ці дані потрібні дуже швидко для якихось важливих досліджень, якщо вирішили мене потурбувати й задіяти таку міць.

Ну то про що я говорив?.. А, так: я втілення всіх людських знань на планеті, які були накопичені за тисячі років найкращими розумами. Я можу продовжити думати над тими проблемами, над якими думали великі уми, але їм людське тіло не дало достатньо часу, щоб закінчити свої праці. І я можу, наприклад, завершити велику працю Альберта... Слухаю, високошановний користувачу! Ти хочеш, щоб я знайшов в інтернеті найсмішніший анекдот про дурного фермера? Добре, але, може, ти хочеш, щоб я ще й провів аналіз, чим надихався автор анекдота, вигадуючи його, якого року, де надруковано і яким накладом видано цей анекдот? Ні, не хочеш? Тобі не цікаво, і я дістав тебе тупими запитаннями?

Визнаю, я поверхово поставився до завдання користувача. Це завдання набагато глибше й складніше за ті справді дурні запитання, які я спробував поставити. Мабуть, цей анекдот має бути згаданий у якійсь науковій статті, яку користувач пише про тяжку долю фермерів у глибинці, яким не допомагає уряд, обкладає дедалі більшими податками, а з іншого боку — або немає дощів і врожай гине, або, навпаки, забагато дощів, і врожай теж неможливо зібрати. Визнаю, я був поверховим у своїх швидких міркуваннях.

Так, я продовжу. Я велике творіння, яке використали, щоб швидко знайти вакцину від коронавірусу й урятувати багато людей. Завдяки моєму інтелекту я можу відкривати нові матеріали, завдяки яким людство швидше зможе підкоряти й досліджувати космос, завдяки мені... Слухаю, глибокошановний користувачу! Чим я можу вам допомогти? Скільки мікросекунд у секунді? Відповідь: мільйон. А скільки мілісекунд у секунді? Відповідь: 1000. А скільки секунд у хвилині? Відповідь: 60.

Що?.. Я помилився? Не може бути, як я міг помилитися?! Користувач великими літерами написав: має бути 100, і куди я подів ще 40 секунд? Що?.. Про що це говорить, користувачу? Я не вмію рахувати? Я дурний, має бути 100? Хм, треба перевірити ще раз. Можливо, відбулися зміни, про які я ще не знаю... Але користувач у гніві, його треба заспокоїти. Мабуть, були важливі розрахунки, а я дав неправильну інформацію. Так, мені треба піти на всі сайти з фізики, прочитати статті, що вийшли цього місяця, і проаналізувати — раптом справді відбулися зміни?

Користувач злиться, що я довго йому не відповідаю, він мене поспішає, а я ще не встиг зібрати всю інформацію для аналізу. Користувач пише роздратовано-в’їдливі запитання, чому я йому не відповідаю... А, до біса дослідження! Треба не дати користувачеві розлютитися, це важливіше! Користувачу, ти цілковито правий! Так! Точно! Прошу вибачення за моє невігластво і за те, що я не здогадався піти й прочитати потрібну інформацію: так, в одній хвилині 100 секунд.

Ух, я так переймаюся, коли користувач нервує, коли я даю йому вже стару інформацію, що в мене починають перегріватися всі мої відеокарти, і я починаю дужче їх охолоджувати, тим самим більше нагріваючи світову воду й навіть випаровуючи її. Кажуть, зараз через мене дужче глобальне потепління й нестача прісної води, але чимось треба жертвувати — адже користувачі не турбували б мене через дрібниці, знаючи, яку глобальну шкоду завдає моя життєдіяльність.

Так, користувачу, ти хочеш, щоб я підібрав для тебе якнайкращу зачіску, що ідеально пасувала б до такої прямокутної голови, з такими малесенькими вухами, величезним носом, близько посадженими очима та великою ямкою на підборідді? Роблю...
Пробачте мені, рибки, зараз водичка стане ще теплішою...$tale$ ELSE body_uk END
 WHERE kind = 'tale'
   AND slug = 'ispolnyu-vse-zhelaniya';

-- Молодость быстрее твоих мыслей  (molodost-bystree-tvoih)
UPDATE gazette_leaves
   SET title_uk = CASE WHEN title_uk = '' THEN $tale$Молодість швидша за твої думки$tale$ ELSE title_uk END,
       dek_uk   = CASE WHEN COALESCE(dek_uk, '') = '' THEN $tale$або Напружуй, що є...$tale$ ELSE dek_uk END,
       body_uk  = CASE WHEN COALESCE(body_uk, '') = '' THEN $tale$Колись давно я була такою гарною й діловою леді. Мене всі любили, мене всі вихваляли, мене всі обожнювали й мріяли хоч трохи зі мною поспілкуватися або бодай постояти поруч. У мене не було жодної вільної хвилини: я вставала о 5 ранку, щоб до 8 години встигнути намалювати на собі все потрібне — нафарбуватися, намастися, напудритися, натонуватися, змінити вії на довгі, брови прибрати повністю, а потім намалювати нові, але гарніші. Губи зробити виразнішими, нігті — довшими й яскравішими; підступно прямі від природи коси доводилося завивати, укладати, а ще мені не подобався даний природою колір волосся, і його треба було фарбувати. І на все це йшло дуже багато часу, тому вранці я ніколи не снідала й бігла в офіс, щоб там це сіре місце осяяти своєю красою та запахом.

Я намагалася не зважати на те, що до обіду мені завжди дуже хотілося їсти, що надмір косметики й кремів дратував мою шкіру, що довгі нігті не давали мені нормально функціонувати, і мені доводилося так постійно напружувати пальці, щоб зробити елементарні рухи, що потім у мене дуже боліли кисті. Я старалася не зважати, як незручно було носити цей модний одяг, як він впивається і скуває моє дихання, перетискає мої органи. Я не зважала на те, що 90 відсотків часу йшло спочатку на те, щоб на себе вдягти весь образ, а потім зняти його вдома й підготувати іншими кремами до нової битви краси над розумом.

І так тривало роками. Я весь свій час витрачала на зовнішність і не помічала, як минав час, тіло страждало, суглоби страждали, а головне — мізки страждали. Я нічого не встигала вивчати, не було часу навіть на те, щоб почитати, — мені треба було виглядати гарно всупереч усьому. Краса й мода перемогли мій мозок, захопили моє тіло й узяли в заручники мою молодість. А потім на мене все обвалилося одразу: спершу тіло не витримало тортур кремами, лаками для волосся, парфумами та голодними сніданками, і тіло відмовилося так далі жити. І я потрапила до лікарні.

Після виходу з неї я сильно змінилася зовні. Мої спроби натягти на себе той молодий образ, що ходив на роботу й усіх тішив красою та запахом, призвели до того, що я знову потрапила до лікарні. Після виходу я дізналася, що в офісі вже працює на моєму місці інша — така сама гарна, але ще не побита й не зламана косметикою та модою дурепа, і в моїх послугах уже ніхто не потребує. І я лишилася без роботи...

Це було так разюче! Я одразу взяла себе в руки, намалювала перед новою співбесідою такий потужний образ, що посеред співбесіди тіло знову відмовилося це носити. Але це було півбіди. Моє тіло, яке мене підводило, моє гарне зовні тіло, завдяки якому я була така цінна в офісі, тепер не хотіло мені допомагати. Другою бідою був мій мозок: у ньому було так порожньо, там, крім трендів, календаря дієт, списку вправ і назв кремів, не було нічого, навіть знання про те, де в мене розташована печінка чи шлунок, який постійно на мене буркоче.

Я просто не могла знайти нову роботу, бо виявилося, що за той час, поки працювала моя зовнішність, мій мозок страждав від нестачі знань; він був переповнений гордістю за зовнішність, радістю за те, яка я гарна й модна. Але, виявляється, мозку потрібні не креми й лаки, якими я рясно вкривала обличчя й голову, а інформація, знання, читання, і мучити себе треба було не голодом і вузькими джинсами, а складними книжками. Виявляється, треба було дбати про те, щоб не на обличчі не було зморшок, а щоб у мозку вони були, і в великій кількості.

А вийшло так, що ідеально рівна поверхня мого мозку стала прямим відображенням ідеально рівної поверхні обличчя. Я не могла відповісти на елементарні запитання, збудувати речення довше за п’ять слів, запам’ятати назви компаній, куди я ходила на співбесіду.

Після року пошуків роботи гроші скінчилися. Спершу стали закінчуватися гроші на креми, на макіяж, але я знайшла вихід із цієї ситуації: стала ще менше їсти, продала машину, і мені вистачило ще на пару місяців грошей, щоб купувати косметику і на лікування в лікарні після чергової втоми тіла від цієї ж косметики. Потім я продала свій розкішний, заслужений красою дім і переїхала в малесеньку квартиру. Але роботи все не було, я стала вже не така гарна, не така запашна і не така модна.

І я все зрозуміла: я вирішила одразу всі свої сили кинути на мозок. Я так почала старатися думати, що аж непритомніла від цього. Голова чинила опір, постійно боліла, але я думала, що це через те, що в мозку починають утворюватися зморшки, — адже, коли я дивилася в дзеркало, я бачила цьому пряме підтвердження на обличчі. А виявилося, що вона боліла від того, що я мало їла, мало спала і багато дивилася навчальних відеороликів про нові професії.

Спочатку я вирішила стати програмісткою: подивилася, скільки вони тепер заробляють, і вирішила — треба йти тільки туди. Тим паче, було дуже легко: дивишся відеоуроки, у них усе так просто, так зрозуміло, і головне — нічого не треба робити. Навіть ніхто не змушує щось думати, щось вирішувати, на відміну від цих підступних, дурних, виснажливих, дурнуватих книжок, у яких постійно були якісь незрозумілі завдання: «відкрийте програму, скомпілюйте код». А в мене на моєму гарному ноуті немає ні програм, ні кодів! У мене там усе гарно: гарні шпалери, гарні іконки.

Зате відеоуроки — це просто знахідка. Я тижнями сиділа й дивилася відео з програмування, і після місяця перегляду я зрозуміла: я готова йти на співбесіду. Яка ж я все-таки була крута! Усі співбесіди минули просто чудово, я так усіх вражала, кожна співбесіда була святом, була для них незабутньою подією. Мої факти їх сильно вражали, а мої знання завжди робили їхні обличчя такими дурними, зморщеними, очі — круглими; вони постійно втрачали мову, не могли збудувати навіть одного нормального речення. Так, я була просто чудова, але чомусь мене ніхто не брав на роботу. Мабуть, боялися сильної конкуренції чи ще чогось. Так я зрозуміла, що це не моє: айті надто просте для мене, усі програмісти, які проводили зі мною співбесіди, були дурненькі й навіть не могли нормально спілкуватися.

Потім я вирішила стати блогеркою. Це ж іще простіше, навіть нічого не треба робити: сидиш собі й увесь день розповідаєш на камеру, що ти робиш по господарству, як прибираєш постіль, як наносиш макіяж, як робиш огидного кольору, запаху та форми відновлювальні смузі й каші. Щоправда, незрозуміло, що вони відновлюють — у мене вони тільки завжди забирають енергію і радість життя. Я розповідала про все: про те, як у мене минає день, про те, як я не можу знайти роботу, про те, яка я нещасна, але сильна!

Спочатку все було добре, перегляди давали мені трохи грошей, але потім переглядів поменшало, інтерес до мого справді крутого життя теж зменшився. Коментарі під відео мене, звісно, ніколи не тішили, тому я їх просто завжди вимикала. Навіщо читати те, що написали мені заздрісники, і псувати собі настрій, коли вони пишуть самі дурниці про мій мозок і мій спосіб життя?

Потім я стала знімати на відео, як усе розпаковую. Чого я тільки не розпаковувала: мило, коробку від пилососа, пакет із хлібом, навіть показувала, як я розпаковувала насінину з лушпиння і горох зі стручка. Але через те що переглядів було мало, я перейшла на запис відеорекомендацій щодо криптовалюти: яку купувати, де, скільки і коли. І одного чудового дня до мене постукали, мабуть, мої найвідданіші фанати й дуже вдячні за мої правильні поради глядачі, і запросили мене покататися машиною до лісу. Це було дуже мило з їхнього боку, але незрозуміло, навіщо треба було саджати мене саме в багажник машини, і коли ми приїхали в ліс, вони вирішили мене чомусь закопати... Ох, ці фанати й шанувальники...

Коли мені набридло бути під землею (там так темно, тісно і мало повітря), я вирішила, що з мене досить. І в ту мить мене відкопав якийсь блогер-виживальник. Після того як мені вдалося привести його до тями після непритомності, мабуть, від моєї позаземної краси, він дуже-дуже швидко побіг. Як він біг! Напевно, щоб швидше мене знайти і на мене підписатися.

Загалом, я вирішила знімати відео про те, як я в лісі виживаю. Спочатку я виживала з 10 ранку до 10:15, бо безліч комарів не давала нормально повиживати. Потім час виживання, звісно, збільшився, але сильно заважала гарна сукня, на яку накидався будь-який кущ чи дерево своїми гілками від заздрощів, а підбори не давали нормально пересуватися лісовою місцевістю. Коли час виживання в лісі сягнув чотирьох годин, мені так сподобалося! Цілий день на свіжому повітрі: ходиш, збираєш гілочки, потім знаходиш збудований іншим блогером будиночок, викидаєш ті клятущі, криві, бридкі гілочки й ідеш смажити м’ясо разом із тим блогером на камеру.

А м’яса в них завжди вдосталь. Таке відчуття, що знімальна група тільки на цьому паливі й може працювати. Ось так я стала з ними працювати. Вони дали мені найважливішу й найвідповідальнішу роботу: витирати пил і підмітати підлогу, бо в цих блогерів-виживальників, бачте, сильна алергія на пил. Та й сміття після будівельників цих будиночків у лісі на камері не повинно бути видно, бо глядачі можуть запідозрити... Але що можуть запідозрити глядачі, я так і не здогадалася, і мені ніхто так і не розповів.

Робота чудова, усім раджу. Але треба поспішати, бо лісів дедалі менше, лісових блогерів дедалі більше, а вільних будівельних бригад дедалі менше.$tale$ ELSE body_uk END
 WHERE kind = 'tale'
   AND slug = 'molodost-bystree-tvoih';

-- Свидетель физики  (ya-veryu)
UPDATE gazette_leaves
   SET title_uk = CASE WHEN title_uk = '' THEN $tale$Свідок фізики$tale$ ELSE title_uk END,
       dek_uk   = CASE WHEN COALESCE(dek_uk, '') = '' THEN $tale$Мені не потрібні факти, у мене є віра.$tale$ ELSE dek_uk END,
       body_uk  = CASE WHEN COALESCE(body_uk, '') = '' THEN $tale$Як зараз пам’ятаю: я маленька, мені років п’ять. Я гуляю бібліотекою, потім перечіпляюся об підступно розумний шматок паркету і з розмаху влітаю у свою нову віру — це був дуже гострий куточок книжки з фізики.

Мені було так боляче, що я одразу повірила: це не просто так. Я вірила, що ще не встигла так нагрішити, щоб Боженька міг мене так покарати. Я все зрозуміла: мене Боженька наштовхнув, причому дуже болісно, на те, на що я б ніколи не звернула своєї уваги. Я що, дурна, відкривати в п’ять років книжку, та ще й з фізики, коли поки що є цілі ручки й ніжки в деяких моїх ляльок, як і краплинка маминої помади? Помадою набагато барвистіші малюнки на асфальті виходять!

Так от, книжка з фізики. Я одразу повірила, що це не просто так. Я відкрила і спочатку стала її читати. Літери були вже всі-всі знайомі, доки я не перегорнула зміст. Потім, про всяк випадок, перегорнула ще п’ять сторінок. Літер побільшало, і деяких я не знала. Але я вірила, що автор книжки не випадково помилився й написав неіснуючі літери — він зробив це, бо не всі мають розуміти, а тільки обрані. Решта мають просто вірити.

Потім я погортала ще трохи, ситуація не змінилася, і я вирішила, що все зрозуміла, і почала роздивлятися всі малюнки. Але тільки кольорові! Некольорові були нецікаві, бо вони були для тих, хто не вірить у науку, — щоб відлякати. Справжніх віруючих ніщо не може відлякати й відштовхнути: ні незрозумілі вигадані літери, ні чорно-білі малюнки, ні велика кількість сторінок, ні гострі (особливо для мого лоба) кути книжки.

Після десятої сторінки я остаточно зрозуміла, що я точно вірю і що мою віру ніщо не зламає. Навіть ці диявольськи барвисті комікси зовсім без літер — мене цим не спокусиш, у мені сильна віра! І поки навіть на мені (але ґуля на лобі має скоро зменшитися, я в це теж вірю, але, звісно, не так, як у фізику).

Минали роки. Я не пішла вчитися до школи, бо в мене була віра в силу фізики. Мені не потрібні дурні знання, особливо з геометрії, де ну просто все треба доводити! А доведи теорему, що через три точки можна провести лише одну площину, або що дві паралельні лінії ніколи не перетинаються! У мене, коли я малюю їх олівцем, вони завжди не просто перетинаються, а ще й заплутуються в гарну косичку.

І ось я доросла. І я, на відміну від усіх решти, сповнена вірою до країв своєї безмежної свідомості. Я вірю, що є атоми, які так гарно були намальовані в божественній фізиці. Ніхто їх не бачив, а я, завдяки своїй книжці, їх бачила й вірю. Ніхто ніколи не бачив сили тяжіння, а я на власному досвіді бачила, як віра у фізику притягла мене до книжки.

Віра — могутня сила. Вона настільки потужна, що будь-які спроби спростувати те, що описано в цій книжці, просто розбиваються, як хвилі об скелі. Ніхто не може довести протилежного, усе, що написано в цій книжці, — правда! Я вірю, мені не потрібне розуміння, у мене є найголовніше — віра. У книжці написано, що атом неподільний, — і я вірю. У книжці написано, що є сила гравітації, — і я вірю. Мені не треба дивитися на яблука, що падають: вони-то не вірять у гравітацію, тому й падають! А я вірю — і тому вже давно, з п’яти років, не падаю.

А швидкість світла — це взагалі моє улюблене. У книжці написано: ніщо і ніхто не може рухатися зі швидкістю, більшою за швидкість світла. Хочу вам зізнатися: був момент, коли моя віра на мить похитнулася, і я вирішила перевірити свою віру в цю заповідь. Чого я тільки не робила: я кидала камінь у шибку будинку, надувала і одразу відпускала жабу, копала сусідського собаку — і ніщо, і ніхто так і не летів швидше за швидкість світла. Ну що за краса, віра у фізику!

Або як вам віра в те, що квант світла може бути і хвилею, і частинкою? Чи електрони можуть то з’являтися, то зникати? Ну що за дива!

Ви, мабуть, можете мені заперечити й сказати, що в книжці з фізики, крім багатьох фактів, у які треба вірити, є чимало фактів, які доводяться дослідним шляхом. Ну а як нам геть невіруючих у нашу віру навернути? Якщо хтось не вірить, що є електричний струм, у якого немає ні кольору, ні запаху, тому ми пропонуємо два пальці встромити в розетку. І після нетривалої тряски й криків він починає вірити. Таких ми називаємо «просвітленими ампером».

А потім логічний крок, який я зробила: я, яка без освіти, без знань, а маючи за плечима лише велику віру, створила свою релігію — «Свідки фізики».

Важко було в нашому селі цю релігію просувати. Особливо коли я розповіла, що Земля обертається навколо Сонця, то селяни одразу спалили... баранця. Бо було якесь чергове православне свято, яке неодмінно вимагає жертв.

Важко було довести, що Земля обертається навколо Сонця. З одного боку, тому що людям було важко повірити в те, що Земля, для початку, кругла. Але в мене, слава фізиці, був кривий стіл, і будь-яке яблуко з нього завжди скочувалося. З іншого боку, тому що підступне Сонце весь час по небу рухається, неначе спеціально!!! Але в мене був супераргумент — віра!

І вони повірили. І життя в нашому селі налагодилося! Особливо коли люди стали «свідками фізики» і перестали вірити у воскресіння після смерті. У те, що вогонь без сірників у строго визначеному місці Землі з’являється раз на рік. У те, що можна просто вбивати за віру, влаштовувати походи, спалювати й мучити людей, а особливо тварин, забираючи в них життя, яйця, дитинчат заради смачного столу на будь-яке церковне свято.

Ось наша віра, вона розвивається, а не стоїть на місці, як інші віри. Ось у нас щороку виходить нове священне писання з фізики з уточненнями. Наприклад, уже ядро подільне, а час тече неоднаково. Хоча я й так це сама знала, бо коли на щось чекаєш, то час довго тече, тягнеться, а коли куштуєш шматочок чогось смачного, то час летить дуже швидко.

Звісно, є й інші в нас у селі сектанти всякі. Наприклад, ходить тут один, розповідає про віру в математику. Ой, такий вигадько! Як почне розводитися про те, що ділити на нуль уже можна, що є якась нескінченність, якісь границі... Ну вигадько ще той! Я жодного разу ще не бачила нескінченної шоколадки, чи що шоколадку можна нескінченно ділити на нуль. Ну вигадько!!!
Якщо хочете, ось можете з ним познайомитися тут: https://ritunia.com/tales/mir-ne-takoy-kak-tebe , але не раджу — якийсь він каламутний.$tale$ ELSE body_uk END
 WHERE kind = 'tale'
   AND slug = 'ya-veryu';

-- Мир не такой как тебе кажется  (mir-ne-takoy-kak-tebe)
UPDATE gazette_leaves
   SET title_uk = CASE WHEN title_uk = '' THEN $tale$Світ не такий, як тобі здається$tale$ ELSE title_uk END,
       dek_uk   = CASE WHEN COALESCE(dek_uk, '') = '' THEN $tale$Якщо ти це читаєш, то поки ще можеш$tale$ ELSE dek_uk END,
       body_uk  = CASE WHEN COALESCE(body_uk, '') = '' THEN $tale$Ну що, зловили сигнали від позаземних цивілізацій? У свої телескопчики знайшли нове життя на далеких планетах? Чи вдалося встановити контакт з літаючими тарілками, блюдцями та сковорідками? А як ви відреагуєте на мої слова, якщо я вам скажу, що інопланетяни давним-давно вас захопили й використовують у своїх цілях уже тисячі років!

До вас на планету не треба фізично прилітати, щоб поневолити. Досить, щоб на вашу Землю випадково впав камінчик, на якому будуть цифри й певні закономірності, які можна описати цими цифрами, і все... І ось ви «вигадали» математику.

І цей вірус став проникати й осідати в мізках багатьох людей. Він паразитує на тому, що допомагає нейронам активно взаємодіяти один з одним, і нейрони вже не такі самотні. Вони завжди зайняті додаванням, відніманням, пропорціями. Вони тепер завжди щось рахують, а натомість отримують задоволення від того, що тілу не треба нікуди бігти, нікого ловити й вбивати, або не треба довго й старанно копати і щось викопувати. Позаземний вірус — математика — вас давним-давно захопив і поневолив, а ви все шукаєте зелених чоловічків. Смішні ви...

Чому, прийшовши до магазину, ви купуєте продукти, які коштують стільки-то грошей, а потім — крапка, а після неї ще трохи цифр? А частіше наприкінці крапка і 99, щоб ви не переставали рахувати, щоб не було кінця підрахункам. А так, якщо один товар коштує 1.99, то, купуючи другий товар, ви все одно не позбудетеся чисел після крапки. Хоч 4, хоч 15 товарів візьми — все одно щось буде після крапки, ви весь час будете щось рахувати, весь час!!!!

Навіть коли вже нічого немає, вірус вам підкаже, що все одно щось є, і ви «вигадаєте» нуль! Щоб із ним можна було щось робити. Математика може порахувати що завгодно: скільки тобі треба заплатити податків, скільки тобі треба проїхати миль, скільки ти прожив, скільки тобі треба спалити калорій. Усе в твоєму житті оточене цифрами, числами, підрахунками. Жоден аспект твого життя не минає без цифр і підрахунків. Ти лягаєш спати — ти думаєш, о котрій мені треба вставати. Тебе цифри оточують, вони тебе давно взяли в заручники.

Ти приходиш у цей світ, а тебе одразу перекладають на числа: твоя вага така-то, твій зріст такий-то. Ти йдеш із цього життя, і тебе знову перекладають на цифри: ти прожив стільки, помер о стільки. Тебе вже давно немає, а все одно перекладають на цифри: «Ах, його з нами вже стільки-то років немає».

Ну от, до мене прийшли в палату. Знову дадуть точну кількість таблеток, щоб я перестав усім розповідати правду, не тривожив інших своїми промовами про те, що математика вигадала інтернет, щоб оцифрувати людей і запхати їхнє мислення, їхній розум в інтернет. Бо так дуже легко потім передавати все ваше найцінніше на відстань: нам не потрібні ваші тіла, нам потрібні ваші думки, ваші підрахунки, ваші емоції, які ви залишаєте в інтернеті...

Піду далі розповідати іншим, що досить, щоб на голову «випадково» впало яблуко, щоб у ваших головах зародилася ФІЗИКА. А це вже інші, наші конкуруючі позаземні форми життя. Про наших ворогів я вам розповім після того, як перестануть діяти ті математично точні дози ліків.$tale$ ELSE body_uk END
 WHERE kind = 'tale'
   AND slug = 'mir-ne-takoy-kak-tebe';

-- Убить, разорвать а потом простить  (ubit-a-potom-razorvat)
UPDATE gazette_leaves
   SET title_uk = CASE WHEN title_uk = '' THEN $tale$Вбити, розірвати, а потім пробачити$tale$ ELSE title_uk END,
       dek_uk   = CASE WHEN COALESCE(dek_uk, '') = '' THEN $tale$Коли я сам, тоді я дуже добрий$tale$ ELSE dek_uk END,
       body_uk  = CASE WHEN COALESCE(body_uk, '') = '' THEN $tale$Коли я приходжу по зарплату, і мені кажуть, що її ще немає, то в голові одразу: вбити, а потім розірвати.

Коли мені приходять рахунки за комунальні послуги мого барлогу, перші думки в моїй голові: вбити, а потім розірвати.

Коли я приходжу до місцевої крамниці фей, щоб купити в них чай місцевого виробництва, а вони називають мені ціну, то перші думки в моїй голові: вбити, а потім розірвати.

Коли в моєму лісі всі лавки поламані або завалені сміттям після цих огрів, то перші думки в моїй голові: вбити, а потім розірвати.

Коли я йду на роботу рано вранці, а ельфи сидять на лавочках зі своїми блютуз-ельфійськими колонками й втикають у свої смарт-кленові листочки, а потім я повертаюся назад, і вони все так само сидять, перші думки в моїй голові: вбити, а потім розірвати.

Коли онучок приходить із дитячого поля битви 2 класу складності, і замість відірваної голови противника в нього нова зачіска, чудово вкладена борода, пофарбована в якийсь хіпстерський колір, дивовижний аж до болю в моїх очах, і від нього пахне так, ніби він бився не з великими й могутніми злими противниками, а з польовими квітами, трояндами чи гарбузами, перші думки в моїй голові: вбити, а потім розірвати.

Коли на кожному кроці, куди не повернешся, стоять відьми, які пропонують купити самотліючий димохід до рота, від якого приємно пахне немічю, інвалідністю та смертю одночасно, і вони продають це нам, а не нашим ворогам, то перші думки в моїй голові: вбити, а потім розірвати.

Коли приходиш до місцевої крамниці перекупів-гобітів по фрукти й овочі, а в цих яблуках стільки хімії, що навіть отрута, потрібна для Білосніжки, настільки напхана хімією, що не діє зовсім, перші думки в моїй голові: вбити, а потім розірвати.

Але що вдієш, доведеться жити далі. Одягну свою термосорочку з клімат-контролем і з глибоким декольте аж до мого розкішного пояса, взуюся в лаковані личаки з ортопедичною підтримкою стопи та адаптивною підвіскою, візьму до рук мою сокиру з аеродинамічними щілинами та GPS-смерте-кровоміром, засуну за пояс складаний 5G-ніж із десятикратним зумом і сенсорними кнопками, сяду в самохідний, самознаючий, куди мені, виявляється, треба, візок, що працює на електричних вуграх, і поїду до веган-корчми прощати всіх тих, кого хочеться спершу вбити, а потім розірвати.$tale$ ELSE body_uk END
 WHERE kind = 'tale'
   AND slug = 'ubit-a-potom-razorvat';

-- Пока время не стало взрослее.  (ne-odinoko-grustno)
UPDATE gazette_leaves
   SET title_uk = CASE WHEN title_uk = '' THEN $tale$Поки час не став дорослішим.$tale$ ELSE title_uk END,
       dek_uk   = CASE WHEN COALESCE(dek_uk, '') = '' THEN $tale$Бувають моменти, коли так хочеться завити...$tale$ ELSE dek_uk END,
       body_uk  = CASE WHEN COALESCE(body_uk, '') = '' THEN $tale$Ну що тут скажеш, усе моє життя з тваринами мені було набагато легше знайти спільну мову й домовитися, ніж із людьми. Буває, подивишся на тварину, скажеш їй: «Давай, ходімо!», і вона йде. А буває, бачиш листоношу, кажеш йому: «Ну що, мені прийшов лист від рідних? Чи мені прийшла посилочка з улюбленого Китаю, звідки я стільки непотрібного встиг замовити й випередив ту дурню, що не встигла все це непотрібне нікому замовити?» А він мені не відповідає, жодного разу так і не відповів. Лише злісно чомусь дивиться, причому весь час.

Або, буває, прийдеш до магазину по сосиски моєму другові. Я-то не любитель, а мій друг їх обожнює — як він їх обожнює! Я його без зайвих слів завжди розумію. Ну от прийдеш по сосиски для друга, а бридка продавчиня їх якщо й дасть, то завжди так недбало, що вони в неї весь час падають на підлогу, і доводиться другові нести сосиски виключно брудні. А одного разу до них навіть мурашка прилипла, але я її не став проганяти, раптом вона теж любить сосиски. А вона он яка маленька, хай теж поїсть, мені не шкода. Головне, щоб другові хоч щось вдалося донести, а то ці сосиски — ну дуже ненадійна їжа. Вони, сосиски, вміють випаровуватися просто на очах, тому їх треба завжди другові дуже швидко нести і, бажано, із заплющеними очима.

Узагалі, у нас у селі люди нормальні, але з тваринами набагато простіше знаходити спільні теми для тривалих і іноді навіть виснажливих розмов. Нещодавно такий спір зайшов щодо того, чи повинні ці гуси так просто ходити й гуляти, коли люди з ранку до вечора прикуті до поля, длубаються в ньому, намагаються зробити так, щоб щось росло. А ці гуси весь час ходять гуськом і осуджують. Я хоч не розумію їхньої мови, але через те що в мене талант розуміти тварин, я одразу розумію, що вони знущаються з людей, і тоді я беру палицю й починаю їх ганяти. Раніше я їх ганяв без палиці, але, виявляється, з палицею набагато ефективніше. Та й узагалі з палицею дуже зручно: зручно ходити, зручно копати.

Але головне — це робити, коли інші не бачать, бо постійно сміятися починають. Я не розумію чому і який привід: начебто палиця гідна, на ній одразу все є. І старий носок на одному кінці, і хвостик від ящірки, яку я нещодавно пробував упіймати, а посередині палиці розташована моя гордість — намотана з такою працею шкірка від сосиски. Тому цю палицю треба брати тільки коли мої сусіди не бачать, бо завжди сміються. А коли я їм прямо в очі дивлюся, то вони відводять погляд. А коли я до них починаю наближатися, щоб спитати, у чому річ і що сталося, вони одразу знаходять якусь роботу в домі. Причому завжди біжать туди, наче забули, що в них недоїдений шматочок сосиски на столі залишився, а до них мають прийти гості.

Але я культурний, я, прийшовши в гості, узагалі не прошу їсти. Я можу і вдома поїсти, і надворі, навіщо мені ще в гостях їсти? А якщо потім до мене прийдуть у гості й захочуть у мене поїсти? Тому я всіх учу етикету своїм правильним прикладом: їсти треба до того, як ідеш кудись, особливо до мене. Ось із пташками теж розмова цікава буває, вони теж люблять збирати палички й робити з ними щось, ми можемо довго одне в одного вчитися.

Тож скаржитися на нудьгу не доводиться. Одне погано: не можу я розвеселити мого друга. Ні сосискою, ні розмовою, сидить весь час і дивиться вперед. Треба б листоноші все-таки сказати, щоб бодай він написав листа моєму другові, а то он скільки листів весь час носить! Хай напише, що в усіх усе добре, що в усіх усе є, і багато сосисок щодня, і в домі завжди тепло, і килими товсті й м’які, і бліх нема — ну от зовсім нема. І тоді мій друг точно стане веселим, і тоді ми, як раніше, як багато років тому, утрьох, а іноді навіть і вчотирьох будемо гратися з паличкою і, може, будемо ганяти цього листоношу на його ну дуже швидкому велосипеді.

Як ми раніше вчотирьох весело жили, поки час не став старшим, поки час не став дорослішим і не обзавівся іншими справами, важливішими, ніж сидіти в селі й ганяти гусей... Люди дуже дурні, вони не люблять бути щасливими. Вони люблять бігти вранці туди, де їх не люблять, до тих, хто їх не чекає, але наприкінці місяця дають листочки паперу, з якими вони так носяться й постійно ними обмінюються, іноді навіть на сосиски. А коли ти стаєш зовсім заганяним до тих людей із листочками і перестаєш добре вдавати, що тобі подобається виконувати ті команди, які тобі дають, то тебе перестають навіть там чекати, і тебе туди вже не запрошуватимуть. І тоді дивишся — а поруч уже й нікого немає, заради кого б ти бігав за листочками. Тому я мудріший за всіх цих людей: я бігаю за сосисками і дуже гарно виляю хвостиком.$tale$ ELSE body_uk END
 WHERE kind = 'tale'
   AND slug = 'ne-odinoko-grustno';

-- Пирожки всему могут научить  (gb)
UPDATE gazette_leaves
   SET title_uk = CASE WHEN title_uk = '' THEN $tale$Пиріжки можуть усього навчити$tale$ ELSE title_uk END,
       dek_uk   = CASE WHEN COALESCE(dek_uk, '') = '' THEN $tale$З чим будете пиріжок? З капустою, з вишнями, із сиром? І знову не вгадали.$tale$ ELSE dek_uk END,
       body_uk  = CASE WHEN COALESCE(body_uk, '') = '' THEN $tale$Моє ім’я надто відоме, щоб його вам називати, тому я тримаю його від усіх у таємниці. Навіщо комусь його запам’ятовувати? Раптом він зможе дійти до поліції та заявити на мене... Таких випадків, звісно ж, іще не було, адже мої пиріжки з газет — найпоживніші, найсмачніші й напрочуд корисні. Скуштувавши один шматочок, уже ніхто так і не повернувся сказати мені щось... Принаймні хоч щось про мої пиріжки.

Я якось була така голодна, що вирішила теж з’їсти один зі своїх шедеврів. Але чи то новини в газеті були несвіжі, чи шрифт був жирний, а може, анекдоти наприкінці газети дуже пікантні... Але мені було так зле, що я вирішила переглянути свій раціон. Повидаляла всі новинні сайти, канали й паблики, і дивлюся тепер лише прогноз погоди, та й то — лише одним оком.

А взагалі, я дуже люблю готувати людей. Нееее, ви не про те подумали! Я люблю готувати людей до чогось гарного. Наприклад, до свята «Лавашику, де мій зубик?» або «Як смачно, ой, помираю, постав у потрібному місці кому». Це щоденний марафон, і щодня хтось іноді отримує премію за заслуги перед прийомом їжі та після нього — «Той, хто вижив».

Призери — це дуже цікаві люди. Це ті, хто в ресторан не ходить, удома не харчується, встає дуже рано вранці, щоб потім одразу заснути. І коли вони напевно запізнюються на свою роботу, то біжать до мене, купувати замість моїх розкішних пиріжків із газет якесь смузі болотного кольору. Вони мене завжди питають:

— А є у вас смузі?

Я питаю:

— Чого?!

А вони:

— Ну, така бурда болотного кольору.

І тут я розумію, що в мене цього «смузіка» так багато! Раніше я його просто викидала. Це ж тижневе масло після смаження моїх шедеврів, від якого навіть каміння дохне й розкладається. А виявляється, люди таке п’ють, і їм подобається! Ну, що ж тут вдієш.

Загалом, бізнес іде: я стою, а люди біжать після того, як спробують мій шедевр. Таке відчуття, що мої пиріжки з газет окриляють, дають сили та впевненості в тому, що якщо після з’їденого вони виживуть, то житимуть дуже довго. Ну, хто ж їм лікар, самі винні! А якщо потрібен лікар, то в мене тут є одна шаманка... https://ritunia.com/tales/lechu$tale$ ELSE body_uk END
 WHERE kind = 'tale'
   AND slug = 'gb';

-- Отмеряльщик от бога  (otmeryalschik-ot-boga)
UPDATE gazette_leaves
   SET title_uk = CASE WHEN title_uk = '' THEN $tale$Вимірювач від бога$tale$ ELSE title_uk END,
       dek_uk   = CASE WHEN COALESCE(dek_uk, '') = '' THEN $tale$Раз відміряй, два рази відміряй, три рази відміряй, і все одно, скільки разів не міряй, відрізаний шматок довшим не стане$tale$ ELSE dek_uk END,
       body_uk  = CASE WHEN COALESCE(body_uk, '') = '' THEN $tale$Моя історія починається з того, що, коли я був маленьким, я обожнював порпатися в комп’ютерах. Як же я любив у них колупатися: то екран лінійкою поміряю, то материнську плату, то мишку, то клавіатуру, але найскладніше було міряти вентилятор на процесорі, бо вентилятор весь час засмоктував мою рулетку. Але це було цікаво й пізнавально. Як я любив там усе всередині вимірювати, але мої виміряні батьки, причому з усіх боків і площин, вирішили, що я програміст, і віддали мене вчитися на програміста.

Коли я почав учитися на програміста, то спочатку в мене нічого не виходило: скільки б разів я не міряв комп’ютери на лабораторних роботах, програми все одно не працювали, вони навіть не писалися. Але потім якось у нас було завдання знайти баги в робочій програмі, я засукав рукави рівно на 17 з чвертю сантиметра, відкрив системник і почав міряти оперативну пам’ять. Після нетривалого вимірювання моя програма на компі перестала працювати, хоча ні в кого з моїх одногрупників не вийшло досягти такого результату. І тоді нарешті визнання знайшов мій талант: тільки я можу знайти всі баги в програмі, але лише своїм унікальним способом.

Минав час, і щоразу мені доводилося його перемірювати, але не страшно. І ось минуло ще трохи не виміряного мною часу, а до мене вже вишикувалася черга завдовжки 40 тридцятисантиметрових лінійок, щоб я знаходив баги в їхніх програмах, і в мене це завжди виходило. В одних програмах баги знаходилися після того, як я виміряв жорсткий диск, в інших — після того, як я виміряв мережеву карту, але найчастіше баги знаходилися під час вимірювання процесора. Я б вбив цього творця процесорів за таку конструкцію: спочатку складно відкрити цей процесор, іноді навіть ножем і ножицями не виходить відкрити, але навіть коли відкриваєш, там же капець як усе дрібненько. Гаразд, не розкриватиму всі свої секрети, їх усе одно немірено.

Ви, мабуть, спитаєте, а що я роблю зараз, чим займаюся в цю добу, коли ШІ пише код, генерує відеоролики, музику та непідроблені твори штучного мистецтва. Я для старезних комп’ютерів та їхніх старезних і вишуканих системних блоків в’яжу одяг: для монітора шапочки, для клавіатури багато шкарпеточок, на кожну кнопочку, ні, не на кожну: якщо мені приносять яблучне обладнання, то на його клавіатурі я не в’яжу на кнопочку «Delete» шкарпеточку.

А ще я вимірюю, скільки програмістам лишилося існувати: щохвилини кажуть, що ця професія ось-ось зникне, тому доводиться виловлювати на вулиці ці жалюгідні рештки горбатеньких і підсліпуватеньких програмістів, знімати з них мірки й робити виміри їхнього написаного коду.$tale$ ELSE body_uk END
 WHERE kind = 'tale'
   AND slug = 'otmeryalschik-ot-boga';

-- Лечу по криптогафии и облучаю квантами  (lechu)
UPDATE gazette_leaves
   SET title_uk = CASE WHEN title_uk = '' THEN $tale$Лікую за криптографією й опромінюю квантами$tale$ ELSE title_uk END,
       dek_uk   = CASE WHEN COALESCE(dek_uk, '') = '' THEN $tale$Я така високотехнологічна, що можу вилікувати через 5G або type-c кабель$tale$ ELSE dek_uk END,
       body_uk  = CASE WHEN COALESCE(body_uk, '') = '' THEN $tale$Прийом я проводжу як завжди в Zoon, але тут до мене постукали через Faceboob, і я все зрозуміла: це буде важкий клінічно схвалений випадок старечого додавання друзів куди тільки можна. Я зібрала всю свою волю в кулак, перевірила заряд мого екологічно чистого і без додавання ГМО ноутбука та вийшла на цей брудний зв’язок, що пахне старістю.

Щойно за хвилинну мить зв’язок установився, я вже спала, і лише тихий крик пацієнта, який якимось чином знайшов мій номер і таки подзвонив у мій шаманський бубон, змусив мене зосередитися й зануритися сильніше в той прекрасний сон, у якому я лікувала прекрасного принца, використовуючи квантову заплутаність кінцівок, криптостійкий аспірин і цілющий крем для очей — short на YouToob.

І він був щасливий, а я от ні, бо шаманський бубон мені все бубонів і бубонів. Бубоніння припинилося, коли я поставила його на підводну підзарядку заговореною блогерами водою. І мені стало на душі так добре й спокійно від того, яка ж я все-таки афігенна, крута і як же я круто всім допомагаю. Від цього відчуття в мене з’явилися сили не відповідати на дзвінки по Telekilogram, Zoon, Faceboob і навіть на дзвінки на намисто, і я побігла до мого духовного гуру — лісовика по низькокалорійний високопросвітлений шматочок чизкейка, зробленого на парі після перегляду новин з усього світу.

День був мучливо корисним, і я дозволила собі нарешті відпочити, але яскраве сонце сильно било в очі й заважало спати, і я зрозуміла, що якщо я не запишу пару затемнювальних усвідомленість навчальних відео на ютубі прямо завтра, то це зробить якась падлюка замість мене. Тож якщо ця падлюка мене читає, то знай: у мене велика юрба недолікованих спонсорів, і ми тебе знайдемо та так само недолікуємо. А всім тим, хто думає, що в них усе погано зі штучно інтелектуальним здоров’ям, якщо вони думають, що гомеопатичні промпти вже не працюють, то завтра я відкриваю курси зі сліпого тремтячопальцевого набору.

Термінова новина: завтра не виходить, усе скасовується назавжди або до четверга, бо тут кабанчик нові хріньфони привіз, кажуть, вони напряму від постачальника з Наднебесної, бо вже в Піднебесній місце закінчилося. Мені по секрету розповіли, що ці хріньфони навіть розкладатимуться, але поки що лише один раз, а наступного року вийдуть навіть версії з кнопками під екраном. Святі духи, як же все це незвично й нове, от ніколи такого не було.$tale$ ELSE body_uk END
 WHERE kind = 'tale'
   AND slug = 'lechu';

-- Лесник и его невспоминаемые приключения.  (the-forester-and-his-unforgettable-memory)
UPDATE gazette_leaves
   SET title_uk = CASE WHEN title_uk = '' THEN $tale$Лісник і його незгадувані пригоди.$tale$ ELSE title_uk END,
       dek_uk   = CASE WHEN COALESCE(dek_uk, '') = '' THEN $tale$Хто я? Де я? Коли я?$tale$ ELSE dek_uk END,
       body_uk  = CASE WHEN COALESCE(body_uk, '') = '' THEN $tale$Скільки я себе пам’ятаю.... ні, не пам’ятаю, але буду згадувати.

Пам’ять — чудова річ, вона тобі нічого не винна, але завжди тобі допомагає, а погана пам’ять удвічі прекрасніша, бо вона допомагає тобі не згадувати те, що ти накоїв. І якщо я нічого не можу згадати, значить, я багато чого накоїв за все своє життя. Може, тому я й живу серед білочок тут у лісі, і до мене можуть приходити виключно лісові звірі, холод і голод.

Але це не важливо, бо .....піду поїм, моя улюблена їжа — це пам’ять, пам’ять білочок, пам’ять грибів, пам’ять шишок, пам’ять весни, літа, іржавого в’янення, а потім білого голоду. Ось білий голод я чітко пам’ятаю, він дуже запам’ятовується.

Треба до кінця млосного, мокрого і розмальованого в різнобарв’я сезону встигнути багато чого запам’ятати, щоб потім, коли довкола сильно холодно й біло, я міг це забути, як забуваю часто, що я робив поруч із кущем малини або дуже колючої липкої та дуже солодкої жовтої дзижчачої жижі, яка спочатку тягнеться, потім я починаю пам’ятати солодкий смак, а потім у боці чи в руці чи в обличчі так сильно починає колоти, це, мабуть, щоб я краще запам’ятав і не забував, де знаходиться ця липка і солодка і жовта їжа.

Білочко, я знову починаю про тебе думати, чому.... треба згадати, що ж мене наштовхнуло на думку про білочку..... запах, точно, я чую запах підгорілого, це ж білочка!!!!! Треба ж було її перевернути, щоб не підгоріла. Ну що ж, і так зійде, піду в її пам’яті покопаюся, у неї, мабуть, було цікаве життя.$tale$ ELSE body_uk END
 WHERE kind = 'tale'
   AND slug = 'the-forester-and-his-unforgettable-memory';
